#include <stdio.h>
int main(void) {
    char s[] = "C is fun to learn";
    int words = 0, in = 0;
    for (int i = 0; s[i]; i++) {
        if (s[i] == ' ') in = 0;
        else if (!in) { in = 1; words++; }
    }
    printf("words=%d\n", words);
    return 0;
}

