#include <stdio.h>
#include <string.h>
#include <ctype.h>
int main(void){char s[64];if(!fgets(s,sizeof s,stdin))return 1;s[strcspn(s,"\n")]=0;int v=0,n=(int)strlen(s),p=1;for(int i=0;i<n;i++){char c=tolower((unsigned char)s[i]);if(c=='a'||c=='e'||c=='i'||c=='o'||c=='u')v++;}for(int i=0,j=n-1;i<j;i++,j--)if(s[i]!=s[j])p=0;printf("len=%d vowels=%d palindrome=%s\n",n,v,p?"yes":"no");return 0;}
